using namespace std;
int main() {
    string str = "How AI-based Assistants are Revolutionizing Customer Service";
    int sum = 0;
    int wordCount = 1; // initialize to 1 since there is at least one word in the string
    for (int i = 0; i < str.length(); i++) {
