```c++
#include <iostream>
#include <cstdlib>
#include <ctime>
using namespace std;
// Function to simulate rolling a six-sided die
int rollDice() {
    return rand() % 6 + 1;
}
// Function to simulate a player's turn
int playerTurn(string playerName) {
    int turnScore = 0;
    int roll = 0;
    char choice = 'r';
    cout << playerName << "'s turn." << endl;
    do {
        roll = rollDice();
        cout << "You rolled a " << roll << "." << endl;
        if (roll == 1) {
            cout << "Sorry, your turn score is zero." << endl;
            turnScore = 0;
            break;
        }
        else {
            turnScore += roll;
            cout << "Your current turn score is " << turnScore << "." << endl;
            cout << "Do you want to roll again (r) or hold (h)? ";
            cin >> choice;
        }
    } while (choice == 'r');
    return turnScore;
}
// Function to simulate the Pig game
void playPig() {
    int player1Score = 0;
    int player2Score = 0;
    int turnScore = 0;
    char choice = 'r';
    bool player1Turn = true;
    srand(time(NULL));
    cout << "Welcome to Pig!" << endl;
    do {
        if (player1Turn) {
            turnScore = playerTurn("Player 1");
            player1Score += turnScore;
            cout << "Player 1's total score is " << player1Score << "." << endl;
            cout << "Player 2's total score is " << player2Score << "." << endl;
        }
        else {
            turnScore = playerTurn("Player 2");
            player2Score += turnScore;
            cout << "Player 2's total score is " << player2Score << "." << endl;
            cout << "Player 1's total score is " << player1Score << "." << endl;
        }
        if (player1Score >= 100 || player2Score >= 100) {
            break;
        }
        cout << "Do you want to continue playing (c) or quit (q)? ";
        cin >> choice;
        if (choice == 'q') {
            break;
        }
        player1Turn = !player1Turn;
    } while (true);
    if (player1Score >= 100) {
        cout << "Player 1 wins!" << endl;
    }
    else if (player2Score >= 100) {
        cout << "Player 2 wins!" << endl;
    }
}
// Main function to start the program
int main() {
    playPig();
    return 0;
}
```
The `rollDice()` function generates a random number between 1 and 6, simulating the roll of a six-sided die. The `playerTurn()` function simulates a player's turn, allowing them to roll the die multiple times and choosing when to hold their turn score. The `playPig()` function simulates the entire game, alternating turns between two players until one of them reaches a total score of 100 or more. 
To run the program, simply compile and execute the code. The program will prompt the players to roll or hold their turn scores, and will display the current total scores after each turn. The program will also ask if the players want to continue playing or quit after each turn. Once a player reaches a total score of 100 or more, the program will declare them the winner and end the game.

