func findTwoPrimesAddingUpToCompositeNumber(_ n: Int) -> (Int, Int)? {
    // Check if the input is a composite number
    guard !isPrime(n) else { return nil }

    // Loop through all prime numbers less than n/2
    for i in 2...(n/2) {
        if isPrime(i) && isPrime(n-i) {
            return (i, n-i)
        }
    }

    return nil
}
func isPrime(_ n: Int) -> Bool {
    // 1 is not a prime number
    if n <= 1 { return false }

    // Check if n is divisible by any number less than n
    for i in 2..<n {
        if n % i == 0 {
            return false
        }
    }

    return true
}
